// Build T3 Code's generated files. Run after editing any Desktop or web source:
//
//   node plugins/t3code/scripts/build.mjs          (uses esbuild from hermes-agent/node_modules)
//   node plugins/t3code/scripts/build.mjs --check  (exit 1 if the generated files are stale)
//
//   shared/desktop/shell.js + features/*/desktop.js  →  <home>/desktop-plugins/t3code/plugin.js (Desktop half)
//   features/orchestrator/web.js                     →  dashboard/dist/index.js (web dashboard tab)
//
// Written straight into Hermes Desktop's plugin folder as a standalone Desktop plugin (on by
// default, hot-reloaded on save). Not shipped as plugins/t3code/desktop/: Hermes installs a
// package's desktop half switched OFF until enabled by hand, which hid the whole UI.
import fs from 'node:fs'
import path from 'node:path'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const hermesAgent = process.env.HERMES_SOURCE_ROOT || path.resolve(root, '../../hermes-agent')
const esbuild = createRequire(path.join(hermesAgent, 'package.json'))('esbuild')
const check = process.argv.includes('--check')
const desktopOut = process.env.T3CODE_DESKTOP_OUT || path.resolve(root, '../../desktop-plugins/t3code/plugin.js')

const BANNER = `// GENERATED by plugins/t3code/scripts/build.mjs — do not edit.
// Sources: shared/desktop/*.js (shell + isolation) and features/<feature>/desktop.js.`

const outputs = []

const bundle = await esbuild.build({
  entryPoints: [path.join(root, 'shared/desktop/shell.js')],
  // Source-path comments are relative to this; pinned so the output is the same from any cwd.
  absWorkingDir: root,
  bundle: true,
  format: 'esm',
  platform: 'browser',
  target: 'es2022',
  // The runtime loader only allows these two imports; everything else is inlined.
  external: ['@hermes/plugin-sdk', 'react'],
  banner: { js: BANNER },
  legalComments: 'inline',
  write: false,
  logLevel: 'warning'
})
outputs.push([desktopOut, bundle.outputFiles[0].text])

const web = fs.readFileSync(path.join(root, 'features/orchestrator/web.js'), 'utf8')
outputs.push([
  path.join(root, 'dashboard/dist/index.js'),
  `// GENERATED by plugins/t3code/scripts/build.mjs from features/orchestrator/web.js — do not edit.\n${web}`
])

let stale = 0

for (const [file, text] of outputs) {
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null

  if (current === text) {
    continue
  }

  stale += 1

  if (check) {
    console.error(`stale: ${file}`)
  } else {
    fs.mkdirSync(path.dirname(file), { recursive: true })
    fs.writeFileSync(file, text)
    console.log(`wrote ${file} (${(text.length / 1024).toFixed(0)} KB)`)
  }
}

if (check && stale) {
  process.exit(1)
}

if (!stale) {
  console.log('up to date')
}
